def classify(addr):
    # 本机：含 localhost 或以 127. 开头
    if "localhost" in addr or addr.startswith("127."):
        return "本机"
    # 内网：192.168. 或 10. 开头
    if addr.startswith("192.168.") or addr.startswith("10."):
        return "内网"
    # 内网：第一段是 172 且第二段在 16~31
    parts = addr.split(".")
    if parts[0] == "172":
        n = int(parts[1])
        if 16 <= n <= 31:
            return "内网"
    return "公网"

